class Solution {
    public int maxCoins(int[] nums) {
        int[] nums2 = new int[nums.length+2];
        System.arraycopy(nums, 0, nums2, 1, nums.length);
        nums2[0]=1;
        nums2[nums2.length-1]=1;
        int n = nums.length;
        int[][] dp = new int[n+2][n+2];
        for (int i = n; i >=1 ; i--) {
            for(int j=1; j<=n; j++){
                if(i>j) continue;
                int maxi = Integer.MIN_VALUE;
                for(int idx=i; idx<=j; idx++){
                    int coins = nums2[i-1] * nums2[idx] * nums2[j+1] + dp[i][idx-1] + dp[idx+1][j];
                    maxi = Math.max(maxi, coins);
                }
                dp[i][j] = maxi;
            }
        }
        return dp[1][n];
    }
}
